# input your yak code
yakit.AutoInitYakit()

# Input your code!
yakit.EnableTable("路径提取",["全路径","基路径","中间路径","方法路径"])

# 全路径存放列表
allUrlSet = container.NewSet();
# 基路径存放列表
baseUrlSet = container.NewSet();
# 中间路径存放列表
midUrSet = container.NewSet();
# 方法名存放列表
methodUrlSet = container.NewSet();

// // 处理URL 去掉协议域名端口
func getURI(urlStr){
    urlStr = re.ExtractPath(urlStr)
    urlStr = str.TrimSuffix(urlStr[0], "?" /*type: string*/)
    yakit.Info(f`获取到完整URL：${urlStr}`)
    return urlStr
}

// 获取后缀名，用来排除JS等不相关文件
func getSuffix(urlStr) {
    path := str.Split(urlStr, "?")[0]
    fileExt := file.GetExt(path)
    return fileExt
}

// 获取所有URL
yakitFlow = yakit.QueryHTTPFlowsAll()
for flow in yakitFlow{
    if flow['FromPlugin'] == false && !str.Contains(flow['Url'], ".js"){
        uris = str.Split(getURI(flow['Url']), "?")[0]   // 去除参数，获得全路径
        yakit.Info(f`获取到全路径：${uris}`)
        allUrlSet.Append(uris)   // 存放全路径
        routeAndMethodUri = file.Split(uris)  // 拆分全路径，获得目录+方法
        yakit.Info(f`获取到方法路径：${routeAndMethodUri[1]}`)
        methodUrlSet.Append(routeAndMethodUri[1]) // 存放方法名
        routeAndMethodUri = str.TrimLeft(routeAndMethodUri[0], "/")
        baseAndMidUri = str.SplitN(routeAndMethodUri, "/", 2 /*type: int*/)   // 拆分基路径和中间路径
        yakit.Info(f`获取到基路径：${baseAndMidUri[0]}`)
        baseUrlSet.Append(baseAndMidUri[0])
        try {
            yakit.Info(f`获取到中间路径：${baseAndMidUri[1]}`)
            midUrSet.Append(baseAndMidUri[1])
        } catch err {
            println("未获取中间路径")
        }
    }

}


// set集合转为list方便取值和计算长度
func setToList(urlSet) {
    urlList = make([]string)
    for num,url = range urlSet {
        urlList.Append(url)
    }
    return urlList
}
allUrlList = setToList(allUrlSet)
baseUrlList = setToList(baseUrlSet)
midUrlList = setToList(midUrSet)
methodUrlList = setToList(methodUrlSet)
// // 输出到表格
maxLen = max(
    len(allUrlList),
    len(baseUrlList),
    len(midUrlList),
    len(methodUrlList)
)

for i := 0; i < maxLen; i++ {
    
    row = make(map[string]var)
    // 动态安全赋值
    if i < len(allUrlList) { row["全路径"] = sprint(allUrlList[i]) }
    if i < len(baseUrlList) { row["基路径"] = sprint(baseUrlList[i]) }
    if i < len(midUrlList) { row["中间路径"] = sprint(midUrlList[i]) }
    if i < len(methodUrlList) { row["方法路径"] = sprint(methodUrlList[i]) }
    yakit.Output(yakit.TableData("路径提取", row))
    
}
